(function(E){ const x = E["exam-05"] = E["exam-05"] || {units:{}}; (x.units = x.units || {})["x05-l1"] = {"id":"x05-l1","patterns":["L1-home","PARA-money","PARA-time"],"title":{"en":"Listening Part 1: choosing a restaurant","tr":"Listening Part 1: restoran seçmek","fa":"Listening Part 1: انتخاب رستوران"},"objective":{"en":"In this lesson you will learn to complete notes while two friends compare three restaurants: follow the headings, catch a detail that changes, choose the right one of two prices, and write a spelled name letter by letter.","tr":"Bu derste iki arkadaş üç restoranı karşılaştırırken notları doldurmayı öğreneceksin: başlıkları takip edecek, değişen bir bilgiyi yakalayacak, iki fiyattan doğru olanı seçecek ve harf harf söylenen bir ismi yazacaksın.","fa":"در این درس یاد می‌گیری وقتی دو دوست سه رستوران را مقایسه می‌کنند، یادداشت‌ها را کامل کنی: عنوان‌ها را دنبال کنی، اطلاعاتی را که عوض می‌شود بگیری، از دو قیمت قیمت درست را انتخاب کنی و اسمی را که حرف به حرف گفته می‌شود بنویسی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 1: choosing a restaurant","tr":"Listening Part 1: restoran seçmek","fa":"Listening Part 1: انتخاب رستوران"},"objective":{"en":"In this lesson you will learn to complete notes while two friends compare three restaurants: follow the headings, catch a detail that changes, choose the right one of two prices, and write a spelled name letter by letter.","tr":"Bu derste iki arkadaş üç restoranı karşılaştırırken notları doldurmayı öğreneceksin: başlıkları takip edecek, değişen bir bilgiyi yakalayacak, iki fiyattan doğru olanı seçecek ve harf harf söylenen bir ismi yazacaksın.","fa":"در این درس یاد می‌گیری وقتی دو دوست سه رستوران را مقایسه می‌کنند، یادداشت‌ها را کامل کنی: عنوان‌ها را دنبال کنی، اطلاعاتی را که عوض می‌شود بگیری، از دو قیمت قیمت درست را انتخاب کنی و اسمی را که حرف به حرف گفته می‌شود بنویسی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word / number","tr":"1 kelime / sayı","fa":"۱ کلمه / عدد"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: three restaurants for a party","tr":"Bu sınav: bir parti için üç restoran","fa":"این آزمون: سه رستوران برای یک مهمانی"},"intro":{"en":"Part 1 is always an everyday conversation in which one person needs information. Here a friend who knows the town helps another friend plan a meal out. Learn the words on the card first: prices, times and booking details are often said in other words.","tr":"Part 1 her zaman birinin bilgiye ihtiyaç duyduğu günlük bir konuşmadır. Burada şehri iyi bilen bir arkadaş, diğerine bir yemek planlamasında yardım ediyor. Önce karttaki kelimeleri öğren: fiyatlar, saatler ve rezervasyon bilgileri çoğu zaman başka kelimelerle söylenir.","fa":"Part 1 همیشه یک گفتگوی روزمره است که در آن یک نفر به اطلاعات نیاز دارد. این‌جا دوستی که شهر را خوب می‌شناسد به دوست دیگرش کمک می‌کند یک شام بیرون را برنامه‌ریزی کند. اول کلمه‌های کارت را یاد بگیر: قیمت، ساعت و جزئیات رزرو اغلب با کلمه‌های دیگری گفته می‌شوند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x05-l1-ctx","exam":true,"patterns":["L1-home","PARA-money","PARA-time"],"often":{"pattern":"L1-home","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Choosing a restaurant for a party","tr":"Bir parti için restoran seçmek","fa":"انتخاب رستوران برای یک مهمانی"},"asks":{"en":"Two friends compare three restaurants for a colleague’s party. The notes have a heading for each place: where it is, the food, the room, the cost, opening times and booking.","tr":"İki arkadaş bir iş arkadaşının partisi için üç restoranı karşılaştırıyor. Notlarda her yer için bir başlık var: nerede olduğu, yemekler, salon, ücret, açılış saatleri ve rezervasyon.","fa":"دو دوست سه رستوران را برای مهمانی یک همکار مقایسه می‌کنند. یادداشت‌ها برای هر جا یک عنوان دارند: کجاست، غذا، سالن، هزینه، ساعت کار و رزرو."},"fields":["Location","Food","Private room","Cost","Name of the place","Menu","View","Opening times","Booking"],"words":[{"a":"deposit","b":"money you pay first and get back later","tr":"depozito, kapora","fa":"بیعانه، ودیعه"},{"a":"per person","b":"a head / each","tr":"kişi başı","fa":"برای هر نفر"},{"a":"set lunch","b":"a fixed menu at one price at midday","tr":"fiks öğle menüsü","fa":"منوی ثابت ناهار"},{"a":"includes","b":"comes with / is part of the price","tr":"dahildir","fa":"شاملِ ... است"},{"a":"holds up to","b":"takes a maximum of / has room for","tr":"en fazla ... kişi alır","fa":"حداکثر ... نفر جا دارد"},{"a":"private room","b":"a separate room just for your group","tr":"özel salon","fa":"اتاق خصوصی"},{"a":"vegetarian","b":"doesn’t eat meat or fish","tr":"vejetaryen","fa":"گیاه‌خوار"},{"a":"book ahead","b":"reserve in advance / give notice","tr":"önceden rezervasyon yapmak","fa":"از قبل رزرو کردن"},{"a":"half past ten","b":"ten thirty / 10.30","tr":"on buçuk","fa":"ده و نیم"},{"a":"famous for","b":"what everyone goes there for","tr":"... ile ünlü","fa":"معروف به"},{"a":"roof terrace","b":"an open area on top of the building","tr":"çatı terası","fa":"تراس روی پشت‌بام"}],"traps":[{"en":"A number that has changed: \"It used to hold forty... they made it smaller, it’s thirty now.\" Write the number that is true today.","tr":"Değişmiş bir sayı: \"Eskiden kırk kişi alıyordu... küçülttüler, şimdi otuz.\" Bugün doğru olan sayıyı yaz.","fa":"عددی که عوض شده: «قبلاً چهل نفر جا داشت... کوچکش کردند، الان سی است». عددی را بنویس که امروز درست است."},{"en":"Two prices: the evening price and a cheaper lunch or group price. Read the words next to the gap to know which one you need.","tr":"İki fiyat: akşam fiyatı ve daha ucuz bir öğle ya da grup fiyatı. Hangisine ihtiyacın olduğunu anlamak için boşluğun yanındaki kelimeleri oku.","fa":"دو قیمت: قیمت شام و یک قیمت ارزان‌ترِ ناهار یا گروهی. کلمه‌های کنار جای خالی را بخوان تا بفهمی کدام را لازم داری."},{"en":"A thing people say, then denied: \"People think it’s mostly pizza, but really it’s the soup.\" What other people think is not the answer.","tr":"Söylenen bir şey, sonra yalanlanıyor: \"İnsanlar çoğunlukla pizza sanıyor ama asıl çorba.\" Başkalarının düşündüğü cevap değildir.","fa":"چیزی که مردم می‌گویند و بعد رد می‌شود: «مردم فکر می‌کنند بیشتر پیتزاست، ولی در اصل سوپ است». چیزی که دیگران فکر می‌کنند جواب نیست."}],"example":{"lines":[["Friend 1","Is the café still open on Sundays?"],["Friend 2","It was last year. Now it’s Saturdays only, because the owner’s got a market stall on Sundays."]],"item":"Café open on ___ only","answer":"Saturdays","why":{"en":"Sundays was last year. \"Now it’s Saturdays only\" is the detail that is true today.","tr":"Pazar geçen yıldı. \"Artık yalnızca cumartesi\" bugün doğru olan bilgi.","fa":"یکشنبه مال پارسال بود. «الان فقط شنبه‌ها» اطلاعاتی است که امروز درست است."}}},{"id":"L1-home","ctx":["L1-home"],"title":{"en":"A service for the home or daily life","tr":"Ev ya da günlük yaşam için bir hizmet","fa":"یک خدمت برای خانه یا زندگی روزمره"},"asks":{"en":"A caller arranges a service such as cleaning, furniture hire, photo copying or a library card, or a friend gives advice on local shops, restaurants or moving house. The notes collect the service, the price, the timing and the conditions.","tr":"Arayan temizlik, mobilya kiralama, fotoğraf aktarma ya da kütüphane kartı gibi bir hizmet ayarlar; ya da bir arkadaş yerel dükkânlar, restoranlar ya da taşınma hakkında tavsiye verir. Notlar hizmeti, fiyatı, zamanı ve koşulları toplar.","fa":"تماس‌گیرنده خدمتی مثل نظافت، اجاره‌ی مبلمان، تبدیل عکس یا کارت کتابخانه را هماهنگ می‌کند، یا دوستی درباره‌ی مغازه‌های محل، رستوران‌ها یا اسباب‌کشی توصیه می‌دهد. یادداشت‌ها خدمت، قیمت، زمان و شرایط را جمع می‌کنند."},"fields":["Service / company name","Address","Number of rooms","Day and time of visit","Price / monthly charge","Delivery","Conditions / insurance","Special requests"],"words":[{"a":"delivery","b":"we bring it to your door","tr":"teslimat","fa":"تحویل"},{"a":"monthly","b":"each month / a month","tr":"aylık","fa":"ماهانه"},{"a":"insurance","b":"cover in case something breaks","tr":"sigorta","fa":"بیمه"},{"a":"contract","b":"you sign up for six months","tr":"sözleşme","fa":"قرارداد"},{"a":"free of charge","b":"at no extra cost / we don't charge for","tr":"ücretsiz","fa":"رایگان"},{"a":"quote","b":"a price we give you first","tr":"fiyat teklifi","fa":"برآورد قیمت"},{"a":"damage","b":"if anything gets broken","tr":"hasar","fa":"خسارت"},{"a":"appointment","b":"we'll book you in for","tr":"randevu","fa":"وقت قبلی"},{"a":"recommend","b":"you should try / the best one is","tr":"tavsiye etmek","fa":"پیشنهاد کردن"},{"a":"nearby","b":"just round the corner","tr":"yakında","fa":"همین نزدیکی"},{"a":"vegetarian","b":"no meat dishes","tr":"vejetaryen","fa":"گیاهی"},{"a":"every other week","b":"once a fortnight","tr":"iki haftada bir","fa":"دو هفته یک بار"}],"traps":[{"en":"The price has parts: a monthly charge plus a one-off delivery fee. Read the heading to know which part it wants.","tr":"Fiyatın parçaları vardır: aylık ücret artı tek seferlik teslimat ücreti. Hangi parçanın istendiğini başlıktan anla.","fa":"قیمت چند بخش دارد: هزینه‌ی ماهانه به‌اضافه‌ی هزینه‌ی یک‌باره‌ی تحویل. از روی عنوان بفهم کدام بخش را می‌خواهد."},{"en":"Offers change the number: \"normally £30, but this month it’s £25\".","tr":"Kampanyalar sayıyı değiştirir: \"normalde 30 pound ama bu ay 25\".","fa":"تخفیف‌ها عدد را عوض می‌کنند: «معمولاً ۳۰ پوند است، ولی این ماه ۲۵»."},{"en":"Street and company names are spelled letter by letter. Write every letter.","tr":"Sokak ve şirket adları harf harf söylenir. Her harfi yaz.","fa":"اسم خیابان و شرکت حرف به حرف هجی می‌شود. همه‌ی حرف‌ها را بنویس."}],"example":{"lines":[["Agent","A cleaner costs fifteen pounds an hour."],["Caller","How many hours for a two-bedroom flat?"],["Agent","Normally three, but the first visit takes four, because we clean the windows too."]],"item":"First visit: ___ hours","answer":"4","why":{"en":"Three is the normal visit. The heading asks about the first visit, which takes four.","tr":"Üç saat normal ziyaret. Başlık ilk ziyareti soruyor; o dört saat sürüyor.","fa":"سه ساعت برای ویزیت معمولی است. عنوان درباره‌ی اولین ویزیت می‌پرسد که چهار ساعت طول می‌کشد."}},"general":true,"patterns":["L1-home"],"often":{"pattern":"L1-home","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Ten gaps in one set of notes","tr":"Tek bir not setinde on boşluk","fa":"ده جای خالی در یک سری یادداشت"},"body":{"en":"All ten questions are notes under three headings, one for each restaurant. You read Questions 1-6 for about 30 seconds, then Questions 7-10 before the second half. The recording plays once and the answers come in order. Limit: ONE WORD AND/OR A NUMBER.","tr":"On sorunun hepsi, her restoran için bir tane olmak üzere üç başlık altındaki notlardır. Önce yaklaşık 30 saniye Soru 1-6’yı, ikinci yarıdan önce de Soru 7-10’u okursun. Kayıt bir kez çalar ve cevaplar sırayla gelir. Sınır: ONE WORD AND/OR A NUMBER.","fa":"هر ده سؤال یادداشت‌هایی زیر سه عنوان‌اند، برای هر رستوران یک عنوان. حدود ۳۰ ثانیه سؤال‌های ۱ تا ۶ را می‌خوانی و قبل از نیمه‌ی دوم سؤال‌های ۷ تا ۱۰ را. فایل یک بار پخش می‌شود و جواب‌ها به ترتیب می‌آیند. سقف: ONE WORD AND/OR A NUMBER."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps for notes","tr":"Notlar için dört adım","fa":"چهار قدم برای یادداشت‌ها"},"steps":[{"en":"Read the headings: when the speakers name the next place, move to the next heading.","tr":"Başlıkları oku: konuşanlar bir sonraki yerin adını söyleyince bir sonraki başlığa geç.","fa":"عنوان‌ها را بخوان: وقتی گوینده‌ها اسم جای بعدی را می‌گویند، برو سراغ عنوان بعدی."},{"en":"For each gap, predict the kind of answer: a number, a price, a time, a place or a dish.","tr":"Her boşluk için cevabın türünü tahmin et: sayı, fiyat, saat, yer ya da yemek.","fa":"برای هر جای خالی نوع جواب را حدس بزن: عدد، قیمت، ساعت، مکان یا غذا."},{"en":"When you hear two numbers or two prices, wait for the one that matches the words next to the gap.","tr":"İki sayı ya da iki fiyat duyduğunda, boşluğun yanındaki kelimelere uyanı bekle.","fa":"وقتی دو عدد یا دو قیمت می‌شنوی، منتظر عددی بمان که با کلمه‌های کنار جای خالی جور است."},{"en":"Write a spelled name exactly as you hear it, letter by letter: \"double T\" means TT.","tr":"Harf harf söylenen bir ismi duyduğun gibi aynen yaz: \"double T\" TT demektir.","fa":"اسمی را که حرف به حرف گفته می‌شود دقیقاً همان‌طور بنویس: «double T» یعنی TT."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"The detail that is true now","tr":"Şu anda doğru olan bilgi","fa":"اطلاعاتی که الان درست است"},"body":{"en":"Speakers often give an old detail first: what a leaflet said, what was true last year, what someone believed. Words like but, actually, since then and now introduce the detail you write. The words printed around the gap tell you which detail is asked for.","tr":"Konuşanlar çoğu zaman önce eski bir bilgi verir: bir broşürde yazan, geçen yıl doğru olan ya da birinin sandığı şey. but, actually, since then ve now gibi kelimeler yazacağın bilgiyi getirir. Boşluğun etrafında yazılı kelimeler hangi bilginin sorulduğunu söyler.","fa":"گوینده‌ها اغلب اول یک مورد قدیمی را می‌گویند: چیزی که یک بروشور نوشته، چیزی که پارسال درست بود، چیزی که کسی خیال می‌کرد. کلمه‌هایی مثل but، actually، since then و now موردی را می‌آورند که باید بنویسی. کلمه‌های چاپ‌شده دور جای خالی می‌گویند کدام مورد خواسته شده."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One gap, step by step","tr":"Bir boşluk, adım adım","fa":"یک جای خالی، قدم به قدم"},"instruction":"Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","item":"Pizza place · group menu costs £___ per person","lines":[["Friend 1","Is the pizza place expensive?"],["Friend 2","Not really. Most pizzas are about fourteen pounds. And if there are ten or more of you, they do a group menu at twelve pounds each, with a drink."]],"answer":"12","walk":[{"en":"Before you listen: the gap needs a price, and \"group menu\" and \"per person\" tell you which price.","tr":"Dinlemeden önce: boşluk bir fiyat istiyor; \"group menu\" ve \"per person\" hangi fiyat olduğunu söylüyor.","fa":"قبل از گوش دادن: جای خالی یک قیمت می‌خواهد و «group menu» و «per person» می‌گویند کدام قیمت."},{"en":"You hear fourteen pounds first, but that is the price of one pizza, not the group menu.","tr":"Önce on dört pound duyuyorsun ama o bir pizzanın fiyatı, grup menüsünün değil.","fa":"اول چهارده پوند را می‌شنوی، اما آن قیمت یک پیتزاست، نه منوی گروهی."},{"en":"\"Twelve pounds each\" = per person. Write 12: the £ sign is printed.","tr":"\"Twelve pounds each\" = kişi başı. 12 yaz: £ işareti zaten yazılı.","fa":"«twelve pounds each» یعنی برای هر نفر. 12 را بنویس: علامت £ چاپ شده."}]},"quick":{"prompt":"Notes: \"Booking: at least ___ days ahead (ONE WORD AND/OR A NUMBER)\". You hear: \"You used to need three days, but now it’s five, because it’s so busy.\" What do you write?","options":["3","5","3 or 5"],"correct":1,"why":{"en":"Three was the old rule. \"But now it’s five\" is the detail that is true today.","tr":"Üç eski kuraldı. \"Ama artık beş\" bugün doğru olan bilgi.","fa":"سه قانون قبلی بود. «اما الان پنج است» اطلاعاتی است که امروز درست است."}},"remember":{"en":"Follow the headings, wait for the detail that is true now, and match the price to the words around the gap.","tr":"Başlıkları takip et, şu anda doğru olan bilgiyi bekle ve fiyatı boşluğun etrafındaki kelimelerle eşleştir.","fa":"عنوان‌ها را دنبال کن، منتظر اطلاعاتی بمان که الان درست است و قیمت را با کلمه‌های دور جای خالی جور کن."},"type":"explain","id":"c-x05-l1-e","course":"ielts-exams","exam":"exam-05","unit":"x05-l1"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 1","title":{"en":"A restaurant for a leaving party","tr":"Veda partisi için bir restoran","fa":"رستورانی برای مهمانی خداحافظی"},"timed":8,"ctx":["L1-home"],"script":[{"who":"Freya","line":"Hi Euan, have you got a minute? It's about Dominic's leaving party."},{"who":"Euan","line":"Sure. Have you found somewhere yet?"},{"who":"Freya","line":"Not yet, that's why I'm calling. You know the restaurants in town much better than I do. I've got a list of three, and I wanted your opinion before I book anything."},{"who":"Euan","line":"Go on, then. What's the first one?"},{"who":"Freya","line":"The Olive Press. Do you know it?"},{"who":"Euan","line":"Yes, I've been there a few times. It's in that old warehouse beside the canal, the one with the big arched windows."},{"who":"Freya","line":"A warehouse? I thought it was in the shopping centre."},{"who":"Euan","line":"No, you're thinking of the Olive Tree. That's a café. The Olive Press is the restaurant by the canal."},{"who":"Freya","line":"OK. And what's the food like? Someone told me it's mainly fish."},{"who":"Euan","line":"I don't think so. They do one or two fish dishes, but what everyone goes there for is the lamb. They cook it slowly for about six hours, and it's absolutely wonderful."},{"who":"Freya","line":"Dominic would love that. How many people can they take? There'll be about thirty of us."},{"who":"Euan","line":"They've got a private room upstairs. When I went last spring it held twenty-five, which wouldn't be enough. But I think they've made it bigger since then. Hang on, I'm looking at their website. Yes, it says the room now takes up to thirty-two."},{"who":"Freya","line":"Perfect. Do they charge for the room?"},{"who":"Euan","line":"Not for the room itself, but you pay a deposit of fifty pounds when you book. You get it back on the night, as long as you don't cancel."},{"who":"Freya","line":"Fine. The second one is a seafood place on the harbour. I can never remember the name. It's something to do with a bird."},{"who":"Euan","line":"Oh, the Kittiwake. It's named after a kind of seagull."},{"who":"Freya","line":"How do you spell that?"},{"who":"Euan","line":"K-I-T-T-I-W-A-K-E. Double T in the middle."},{"who":"Freya","line":"Got it. What's it like?"},{"who":"Euan","line":"Really lively, and the fish comes straight off the boats every morning. It isn't cheap in the evening, though. The main menu works out at about thirty-five pounds a head."},{"who":"Freya","line":"That's a bit much for some people."},{"who":"Euan","line":"But if you did it at lunchtime, they've got a set lunch for eighteen pounds fifty, and that includes a dessert. Dominic finishes on a Friday, doesn't he? You could do a long Friday lunch."},{"who":"Freya","line":"That's a nice idea. I'll suggest it."},{"who":"Freya","line":"Oh, but what about Priya and Tom? They don't eat fish at all."},{"who":"Euan","line":"That's not a problem. The Kittiwake has a completely separate vegetarian menu, and it's not just one pasta dish. My sister doesn't eat meat or fish, and she says it's the best in town."},{"who":"Freya","line":"Great. And the last one on my list is Marlowe's."},{"who":"Euan","line":"Ah, the place with the roof terrace. It's on top of the old department store."},{"who":"Freya","line":"Is the view worth it?"},{"who":"Euan","line":"It's amazing. You look straight across at the cathedral. People sometimes say you can see the sea from up there, but honestly you can't, unless it's a very clear day and you know exactly where to look."},{"who":"Freya","line":"What about opening times? If we went in the evening, people might want to stay late."},{"who":"Euan","line":"During the week they're open until eleven. On Fridays, though, they close at ten thirty. It's something to do with their licence for the terrace."},{"who":"Freya","line":"And is it easy to get a table?"},{"who":"Euan","line":"That's the only problem. It's very popular, so you have to book at least a fortnight ahead. A week isn't enough, they told me that last time."},{"who":"Freya","line":"A fortnight. Dominic's last day is the twentieth, so I'd better be quick."},{"who":"Euan","line":"If I were you, I'd go for the Olive Press in the evening. But a lunch at the Kittiwake would be fun too."},{"who":"Freya","line":"I'll send everyone the options tonight. Thanks, Euan, that's really helpful."},{"who":"Euan","line":"No problem. See you on Monday."}],"notes":{"title":"Restaurants for Dominic’s leaving party","lines":["The Olive Press","Location: in an old (1) ___ beside the canal","Food: best known for its (2) ___","Private room: holds up to (3) ___ people","Pay a £50 (4) ___ when booking","Seafood restaurant on the harbour","Name: the (5) ___","Set lunch: £(6) ___ per person, including dessert","Has a separate (7) ___ menu","Marlowe’s","Roof terrace with a view of the (8) ___","Closes at (9) ___ on Fridays","Book at least a (10) ___ ahead"]},"groups":[{"instruction":"Questions 1-10. Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","qtype":"note","questions":[{"n":1,"kind":"gap","prompt":"The Olive Press · Location: in an old ___ beside the canal","accept":["warehouse"],"limit":1,"evidence":"in that old warehouse beside the canal","why":{"en":"The shopping centre is the café with a similar name. The restaurant is \"in that old warehouse beside the canal\".","tr":"Alışveriş merkezindeki, adı benzeyen kafe. Restoran \"kanalın yanındaki o eski depoda\".","fa":"مرکز خرید مال کافه‌ای با اسم مشابه است. رستوران «در آن انبار قدیمی کنار کانال» است."},"trap":["TR-paraphrase"]},{"n":2,"kind":"gap","prompt":"The Olive Press · Food: best known for its ___","accept":["lamb"],"limit":1,"evidence":"what everyone goes there for is the lamb","why":{"en":"Fish is what someone told Freya; \"what everyone goes there for is the lamb\" = best known for.","tr":"Balık, Freya’ya birinin söylediği şey; \"herkesin oraya gitme sebebi kuzu eti\" = en çok bununla tanınıyor.","fa":"ماهی چیزی است که کسی به فریا گفته؛ «چیزی که همه برایش به آن‌جا می‌روند گوشت بره است» یعنی بیشتر از همه به آن معروف است."},"trap":["TR-paraphrase"]},{"n":3,"kind":"gap","prompt":"The Olive Press · Private room: holds up to ___ people","accept":["32","thirty-two"],"limit":1,"evidence":"the room now takes up to thirty-two","why":{"en":"Twenty-five was last spring. The website says \"the room now takes up to thirty-two\".","tr":"Yirmi beş geçen ilkbahardı. Web sitesi \"salon artık otuz iki kişiye kadar alıyor\" diyor.","fa":"بیست‌وپنج مال بهار پارسال بود. سایت می‌گوید «اتاق الان تا سی‌ودو نفر جا دارد»."},"trap":["TR-selfcorrect"]},{"n":4,"kind":"gap","prompt":"The Olive Press · Pay a £50 ___ when booking","accept":["deposit"],"limit":1,"evidence":"you pay a deposit of fifty pounds when you book","why":{"en":"\"A deposit of fifty pounds\": the money you pay first and get back on the night.","tr":"\"Elli poundluk bir depozito\": önce ödeyip o akşam geri aldığın para.","fa":"«بیعانه‌ی پنجاه پوندی»: پولی که اول می‌دهی و شب مهمانی پس می‌گیری."},"trap":["TR-printed"]},{"n":5,"kind":"gap","prompt":"Seafood restaurant on the harbour · Name: the ___","accept":["Kittiwake"],"limit":1,"evidence":"K-I-T-T-I-W-A-K-E","why":{"en":"Spelled K-I-T-T-I-W-A-K-E: \"double T in the middle\". Every letter must be right.","tr":"K-I-T-T-I-W-A-K-E diye harf harf: \"ortada çift T\". Her harf doğru olmalı.","fa":"حرف به حرف: K-I-T-T-I-W-A-K-E، «وسطش دو تا T». همه‌ی حرف‌ها باید درست باشند."},"trap":["TR-spell"]},{"n":6,"kind":"gap","prompt":"Seafood restaurant · Set lunch: £___ per person, including dessert","accept":["18.50"],"limit":1,"evidence":"a set lunch for eighteen pounds fifty","why":{"en":"£35 a head is the evening menu. The set lunch, with dessert, is £18.50.","tr":"Kişi başı 35 £ akşam menüsü. Tatlı dahil fiks öğle menüsü 18,50 £.","fa":"نفری ۳۵ پوند منوی شام است. ناهار ثابت، با دسر، ۱۸٫۵۰ پوند است."},"trap":["TR-price"]},{"n":7,"kind":"gap","prompt":"Seafood restaurant · Has a separate ___ menu","accept":["vegetarian"],"limit":1,"evidence":"a completely separate vegetarian menu","why":{"en":"\"A completely separate vegetarian menu\". \"menu\" is printed, so write one word.","tr":"\"Tamamen ayrı bir vejetaryen menü\". \"menu\" yazılı, tek kelime yaz.","fa":"«یک منوی گیاهیِ کاملاً جدا». «menu» چاپ شده، پس یک کلمه بنویس."},"trap":["TR-printed"]},{"n":8,"kind":"gap","prompt":"Marlowe’s · Roof terrace with a view of the ___","accept":["cathedral"],"limit":1,"evidence":"You look straight across at the cathedral","why":{"en":"The sea is ruled out (\"honestly you can’t\"). The view is of the cathedral.","tr":"Deniz eleniyor (\"açıkçası göremezsin\"). Manzara katedral.","fa":"دریا رد می‌شود («راستش نمی‌شود دید»). منظره کلیساست."},"trap":["TR-paraphrase"]},{"n":9,"kind":"gap","prompt":"Marlowe’s · Closes at ___ on Fridays","accept":["10.30","10:30"],"limit":1,"evidence":"On Fridays, though, they close at ten thirty","why":{"en":"Eleven is during the week. \"On Fridays, though, they close at ten thirty.\"","tr":"On bir hafta içi. \"Cuma günleri ise on buçukta kapanıyor.\"","fa":"یازده مال روزهای وسط هفته است. «اما جمعه‌ها ده و نیم می‌بندند»."},"trap":["TR-paraphrase"]},{"n":10,"kind":"gap","prompt":"Marlowe’s · Book at least a ___ ahead","accept":["fortnight"],"limit":1,"evidence":"book at least a fortnight ahead","why":{"en":"\"At least a fortnight ahead\"; a week is \"not enough\". A fortnight is two weeks.","tr":"\"En az iki hafta önceden\"; bir hafta \"yetmez\". A fortnight iki hafta demek.","fa":"«دست‌کم دو هفته زودتر»؛ یک هفته «کافی نیست». fortnight یعنی دو هفته."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Freya":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_lily"},"role":"Friend organising the party"},"Euan":{"accent":"Scottish","gender":"M","tts":{"engine":"piper","voice":"en_GB-alan-medium"},"role":"Friend who knows the restaurants"}},"sequence":[{"type":"announcer","text":"Part 1. You will hear a telephone conversation between two friends who are planning a party for a colleague. First, you have some time to look at Questions 1 to 6."},{"type":"pause","seconds":30,"note":"reading time, Questions 1-6"},{"type":"announcer","text":"Now listen carefully and answer Questions 1 to 6."},{"type":"lines","from":0,"to":22,"note":"phone line: light telephone filter on both voices"},{"type":"announcer","text":"Before you hear the rest of the conversation, you have some time to look at Questions 7 to 10."},{"type":"pause","seconds":30,"note":"reading time, Questions 7-10"},{"type":"announcer","text":"Now listen and answer Questions 7 to 10."},{"type":"lines","from":23,"to":36},{"type":"announcer","text":"That is the end of Part 1. You now have half a minute to check your answers.","after":30}]},"id":"c-x05-l1-d","course":"ielts-exams","exam":"exam-05","unit":"x05-l1"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"A friend says the restaurant \"works out at about forty pounds a head\". This means...","options":["it costs about £40 for each person","it costs about £40 for the whole group","the head chef charges £40"],"correct":0,"why":{"en":"\"A head\" = per person.","tr":"\"A head\" = kişi başı.","fa":"«a head» یعنی برای هر نفر."}},{"tests":"paraphrase","point":1,"prompt":"Notes say \"Book at least two weeks ahead\". Which words in a recording mean the same?","options":["you can book up to a week before","book any time in the next fortnight","you need to give them a fortnight’s notice"],"correct":2,"why":{"en":"A fortnight = two weeks; \"give notice\" = tell them in advance.","tr":"A fortnight = iki hafta; \"give notice\" = önceden haber vermek.","fa":"fortnight یعنی دو هفته؛ «give notice» یعنی از قبل خبر دادن."}},{"tests":"method","point":2,"prompt":"The gap is \"Name: the ___\". The speaker spells it: \"M-A-double-L-O-W\". What do you write?","options":["Malow","Mallow","Mallowe"],"correct":1,"why":{"en":"\"Double L\" = LL. Write each letter in the order you hear it.","tr":"\"Double L\" = LL. Her harfi duyduğun sırayla yaz.","fa":"«double L» یعنی LL. هر حرف را به همان ترتیبی که می‌شنوی بنویس."}},{"tests":"trap","point":3,"prompt":"Gap: \"Live music on ___ evenings\". You hear: \"The band used to play on Thursdays, but since the new manager came it’s Saturdays.\" What do you write?","options":["Saturday","Thursday","Thursday and Saturday"],"correct":0,"why":{"en":"\"Used to\" marks the old day; \"since the new manager came\" gives the day now.","tr":"\"Used to\" eski günü gösterir; \"yeni müdür geldiğinden beri\" bugünkü günü verir.","fa":"«used to» روز قبلی را نشان می‌دهد؛ «از وقتی مدیر جدید آمد» روز فعلی را می‌دهد."}},{"tests":"trap","point":2,"prompt":"Gap: \"Children’s menu: £___\". You hear: \"Adults pay twenty-two pounds, and children under twelve pay half that.\" What do you write?","options":["22","12","11"],"correct":2,"why":{"en":"The children’s price is half of £22 = 11. Twelve is the age, not a price.","tr":"Çocuk fiyatı 22 £’un yarısı = 11. On iki yaş, fiyat değil.","fa":"قیمت بچه‌ها نصف ۲۲ پوند است، یعنی ۱۱. دوازده سن است، نه قیمت."}}],"id":"c-x05-l1-x","course":"ielts-exams","exam":"exam-05","unit":"x05-l1"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
